-- =============================================================================
-- University of Nigeria, Nsukka — Faculty of Physical Sciences — Geology
-- Course outlines transcribed from the departmental course handbook.
-- =============================================================================
-- Run in the Supabase SQL Editor. Safe to run more than once: existing rows
-- for these courses are removed first, so it updates rather than duplicates.
--
-- NOTE ON SEMESTERS: the handbook does not state which semester each course
-- runs in. The values below follow the usual Nigerian convention that an odd
-- final digit is first semester and an even one is second. Correct any that
-- differ at UNN by editing the semester column in the Table Editor.
--
-- This file also carries the required ancillary, general-studies and elective
-- courses a Geology student sits each semester, taken from a 2014/2015
-- Faculty of Physical Sciences curriculum booklet's "Five-Year Standard
-- Undergraduate Programme" table for Geology — geology.unn.edu.ng itself
-- publishes no equivalent table (its course-module page reads "Coming Soon"
-- and its programmes page covers postgraduate study only), so this dated
-- source is the only one available. Ancillary descriptions are reused,
-- unedited, from this app's Mathematics/Physics/Chemistry/Statistics/
-- Computer Science outlines where the code, level, semester and subject
-- genuinely match; GSP, FRE, ECE, ZOO and CVE codes carry code/title/units/
-- level/semester only, since no verified description exists anywhere yet.
--
-- GLG 331 (Stratigraphy, 300 Level first semester, 2 units) is added as a
-- major course with no description, since the department's own course
-- descriptions PDF never gives it one, only citing it as a prerequisite for
-- other courses.
--
-- The same booklet's Fifth Year table lists five further major courses —
-- GLG 574 (Tectonophysics), GLG 581 (Hydrogeology), GLG 583 (Engineering
-- Geology II), GLG 591 (Seminar) and GLG 592 (Project) — but the copy
-- photographed cuts off that table's credit-unit column entirely, so their
-- units cannot be verified. They are left out rather than guessed at.
--
-- Two codes in the source are visibly damaged by the book's binding fold and
-- were matched to the only course elsewhere in the same document with the
-- same title: "SP 101" -> COS 101 (Introduction to Computer Science), and
-- "Computer Programming 11" -> COS 201 (Computer Programming I, not II).
-- A third, "E 221" for a Fluid Mechanics elective, is filed under CVE 221 as
-- the closest plausible match, but is not independently confirmed.
-- =============================================================================

delete from public.course_outlines
 where institution = 'University of Nigeria, Nsukka'
   and department = 'Geology';

insert into public.course_outlines
  (course_code, course_title, institution, faculty, department, level,
   semester, credit_units, description, topics, contributor_name)
values
  ('GLG 101', 'Basic and Applied Geology for Agricultural and Biological Sciences', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 3, 'Important minerals and major rock types; geological time scale; study of geomorphic and soil-forming processes; relationship between soil and rock type; elements of structural geology; fossils and their uses; general characteristics of important animal and plant fossil groups; outlines of the geology and mineral resources of Nigeria.', '["Important minerals and major rock types", "Geological time scale", "Study of geomorphic and soil-forming processes", "Relationship between soil and rock type", "Elements of structural geology", "Fossils and their uses", "General characteristics of important animal and plant fossil groups", "Outlines of the geology and mineral resources of Nigeria"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 103', 'Basic and Applied Geology for Environmental and Physical Science', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 3, 'The earth and the solar system; internal structures and physics of the earth; important minerals and major rock types; geologic time-scale and geochronology; elements of earth history; relationship between geomorphic and structural features; weathering and erosion, gullying, landslide, floods, desert advance, and environmental pollution, and their control; outlines of the geology and mineral resources of Nigeria.', '["The earth and the solar system", "Internal structures and physics of the earth", "Important minerals and major rock types", "Geologic time-scale and geochronology", "Elements of earth history", "Relationship between geomorphic and structural features", "Weathering and erosion, gullying, landslide, floods, desert advance, and environmental pollution, and their control", "Outlines of the geology and mineral resources of Nigeria"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 105', 'Basic and Applied Geology for Engineering', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 3, 'Important minerals and major rock types; geologic time scale; elements of physical geology and earth history; physical and engineering properties of rocks; principles and mechanics of rock deformation; study of slopes and their stability; construction materials; essentials of hydrogeology and engineering geology; outlines of geology and mineral resources of Nigeria.', '["Important minerals and major rock types", "Geologic time scale", "Elements of physical geology and earth history", "Physical and engineering properties of rocks", "Principles and mechanics of rock deformation", "Study of slopes and their stability", "Construction materials", "Essentials of hydrogeology and engineering geology", "Outlines of geology and mineral resources of Nigeria"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 111', 'Physical Geology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 2, 'Study of the earth and the solar system; study of minerals - their crystallography, physical and chemical properties; major rock types; geomorphic processes and products; internal processes and products; economic resources of the earth.', '["Study of the earth and the solar system", "Study of minerals - their crystallography, physical and chemical properties", "Major rock types", "Geomorphic processes and products", "Internal processes and products", "Economic resources of the earth"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 142', 'Earth History', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'second', 3, 'The geologic time scale and dating of rocks. Origin and chemical evolution of the atmosphere, hydrosphere and biosphere. Fossils and their uses. Main biological groups to which fossils belong - life through geologic time. Concepts of paleoclimate, paleogeography, paleooceanography, paleomagnetism. Fundamental principles of stratigraphy.', '["The geologic time scale and dating of rocks", "Origin and chemical evolution of the atmosphere, hydrosphere and biosphere", "Fossils and their uses", "Main biological groups to which fossils belong - life through geologic time", "Concepts of paleoclimate, paleogeography, paleooceanography, paleomagnetism", "Fundamental principles of stratigraphy"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 211', 'Crystallography and Mineralogy', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '200 Level', 'first', 2, 'Formation of crystal; crystalline state; laws of crystallography; space lattice and unit cell symmetry elements, goniometry and stereographic projection; crystallographic projection; crystallographic notations; seven crystal systems and 32 classes of crystal symmetry, crystal defects; twinning and twin laws. Principles of crystal chemistry; physical and determinative properties of minerals; systematics of minerals; silicates; description of common rock-forming minerals. Industrial Mineralogy.', '["Formation of crystal", "Crystalline state", "Laws of crystallography", "Space lattice and unit cell symmetry elements, goniometry and stereographic projection", "Crystallographic projection", "Crystallographic notations", "Seven crystal systems and 32 classes of crystal symmetry, crystal defects", "Twinning and twin laws", "Principles of crystal chemistry", "Physical and determinative properties of minerals", "Systematics of minerals", "Silicates", "Description of common rock-forming minerals", "Industrial Mineralogy"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 212', 'Optical Mineralogy', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '200 Level', 'second', 2, 'Properties of light; polarizing microscope; double refraction, refractive index and relief; uniaxiality and biaxiality of crystals; optical indicatrix, optical properties of minerals under polarized, plane-polarized, cross polarized, and convergent-polarized light; determination of optic sign and dispersion X-ray crystallography.', '["Properties of light", "Polarizing microscope", "Double refraction, refractive index and relief", "Uniaxiality and biaxiality of crystals", "Optical indicatrix, optical properties of minerals under polarized, plane-polarized, cross polarized, and convergent-polarized light", "Determination of optic sign and dispersion X-ray crystallography"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 214', 'Introduction to Petrology of Igneous and Metamorphic Rocks', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '200 Level', 'second', 2, 'Properties and chemistry of magma; volcanoes and their products; occurrences of intrusive igneous rocks; mineralogy and texture of igneous rocks; descriptions of various classes of igneous rocks and their metamorphism.

Prerequisite: GLG 111', '["Properties and chemistry of magma", "Volcanoes and their products", "Occurrences of intrusive igneous rocks", "Mineralogy and texture of igneous rocks", "Descriptions of various classes of igneous rocks and their metamorphism"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 222', 'Structural Geology and Map Interpretation', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '200 Level', 'second', 2, 'Principles of rock deformation, attitudes of planes; study of geometry, mechanics and types of deformational structures; primary structures in igneous rocks; problems concerning geologic maps; application of orthographic projection in structural geology; structural mapping practice.

Prerequisite: GLG 151', '["Principles of rock deformation, attitudes of planes", "Study of geometry, mechanics and types of deformational structures", "Primary structures in igneous rocks", "Problems concerning geologic maps", "Application of orthographic projection in structural geology", "Structural mapping practice"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 242', 'Paleobiology I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '200 Level', 'second', 2, 'Rules of nomenclature, sampling and identification of fossils. Taxonomical, morphological and evolutionary studies of the major invertebrate phyla - Protozoa, Porifera, Coelenterata, Bryozoa, Brachiopoda, Mollusca, Arthropoda, Echinodermata, and Graptolithina; their stratigraphic and paleoecologic distribution; introduction to vertebrates, plants and trace fossils.

Prerequisite: GLG 141', '["Rules of nomenclature, sampling and identification of fossils", "Taxonomical, morphological and evolutionary studies of the major invertebrate phyla - Protozoa, Porifera, Coelenterata, Bryozoa, Brachiopoda, Mollusca, Arthropoda, Echinodermata, and Graptolithina", "Their stratigraphic and paleoecologic distribution", "Introduction to vertebrates, plants and trace fossils"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 251', 'Field Geology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '200 Level', 'first', 2, 'Fundamentals of structural geology; description of deformational structures, field mapping techniques (the use of Brunton Compass and clinometer, plane table, etc); study of topographic maps; preparation of simple geologic maps; study of land use and conservation.

Prerequisite: GLG 111', '["Fundamentals of structural geology", "Description of deformational structures, field mapping techniques (the use of Brunton Compass and clinometer, plane table, etc)", "Study of topographic maps", "Preparation of simple geologic maps", "Study of land use and conservation"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 311', 'Petrology of Igneous Rocks', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'first', 4, 'Texture, mineralogy, chemistry, mode of occurrence, and classification of igneous and metamorphic rocks. Magma types; magmatic evolution. Phase rule and thermodynamic principles; crystallization of silicate melts; one-component and two-component systems; eutectic, peritectic, and solid solution series, reaction principles; mineral paragenesis; Systematic petrographic study of major igneous rocks types; methods of normative mineral calculation.

Prerequisite: GLG 212, GLG 213, GLG 214', '["Texture, mineralogy, chemistry, mode of occurrence, and classification of igneous and metamorphic rocks", "Magma types", "Magmatic evolution", "Phase rule and thermodynamic principles", "Crystallization of silicate melts", "One-component and two-component systems", "Eutectic, peritectic, and solid solution series, reaction principles", "Mineral paragenesis", "Systematic petrographic study of major igneous rocks types", "Methods of normative mineral calculation"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 321', 'Structural Geology II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'first', 3, 'Stress and strain; deformational ellipsoid; major deformational structures of the earth; formation of cleavage, schistosity and lineation; mega and micro structures; emplacement of salt domes; plutons and other intrusive bodies; polyphase deformation; structural petrology; Problems concerning geologic maps and structures; stereographic projection in structural geology.

Prerequisite: GLG 221', '["Stress and strain", "Deformational ellipsoid", "Major deformational structures of the earth", "Formation of cleavage, schistosity and lineation", "Mega and micro structures", "Emplacement of salt domes", "Plutons and other intrusive bodies", "Polyphase deformation", "Structural petrology", "Problems concerning geologic maps and structures", "Stereographic projection in structural geology"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 322', 'Aerogeology and Remote Sensing / Geographical Information Systems (GIS)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'second', 2, 'Elements of photogrammetry and photo interpretation; Preparation of photogeologic map; Major satellite programmes; GIS application for Digital Image Processing - image stretching, spatial filtering, band rationing, lineament density analysis, colour composites, principal component analysis, image classification; Geologic application of remote sensing techniques.

Prerequisite: GLG 111', '["Elements of photogrammetry and photo interpretation", "Preparation of photogeologic map", "Major satellite programmes", "GIS application for Digital Image Processing - image stretching, spatial filtering, band rationing, lineament density analysis, colour composites, principal component analysis, image classification", "Geologic application of remote sensing techniques"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 332', 'Sedimentology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'second', 3, 'Origin of sediments; sedimentary processes; hydrodynamic interpretation; quantitative and statistical study of sedimentary rocks; description of sedimentary environments from rock records. Petrographic study of selected thin sections under polarizing microscope.

Prerequisite: GLG 331, GLG 213', '["Origin of sediments", "Sedimentary processes", "Hydrodynamic interpretation", "Quantitative and statistical study of sedimentary rocks", "Description of sedimentary environments from rock records", "Petrographic study of selected thin sections under polarizing microscope"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 334', 'Geology of Nigeria', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'second', 2, 'Distribution and description of Igneous, Metamorphic and sedimentary rocks of Nigeria; structural development and major tectonic elements of Nigeria, Origin of Nigerian sedimentary basins; economic geology of Nigeria.

Prerequisite: GLG 111, GLG 221, GLG 251', '["Distribution and description of Igneous, Metamorphic and sedimentary rocks of Nigeria", "Structural development and major tectonic elements of Nigeria, Origin of Nigerian sedimentary basins", "Economic geology of Nigeria"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 342', 'Paleobiology II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'second', 3, 'Palaeontologic principles and Paleobiologic models. Macro and micro evolution. Taxanomic, morphologic and biostratigraphic studies of the major groups of microfossils especially, foraminifera, pollen and spores; their paleoenvironmental applications.

Prerequisite: GLG 241', '["Palaeontologic principles and Paleobiologic models", "Macro and micro evolution", "Taxanomic, morphologic and biostratigraphic studies of the major groups of microfossils especially, foraminifera, pollen and spores", "Their paleoenvironmental applications"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 351', 'Field Mapping', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'first', 2, 'Techniques in geologic mapping; preparation of geologic maps; practice mapping of selected areas; report writing on field mapping. (Course is to be offered during short vacation or term breaks).

Prerequisite: GLG 251', '["Techniques in geologic mapping", "Preparation of geologic maps", "Practice mapping of selected areas", "Report writing on field mapping", "(Course is to be offered during short vacation or term breaks)"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 362', 'Mineral Resources', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'second', 2, 'Metallic and non metallic mineral resources; their composition, distribution, and utilization; Industrial Minerals; Fossil fuels, surface and underground water hydrology.

Prerequisite: GLG 111, GLG 212, Consent of Lecturer', '["Metallic and non metallic mineral resources", "Their composition, distribution, and utilization", "Industrial Minerals", "Fossil fuels, surface and underground water hydrology"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 364', 'Mining Geology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'second', 2, 'History of Mining; Exploration - Geology - Reserves; Mining equipments; mining methods; Blast design and Assessment for surface mines and quarries, underground mines, exploring drilling; mining safety; mineral processing; mining laws; mine administration and management.

Prerequisite: GLG 111, GLG 251', '["History of Mining", "Exploration - Geology - Reserves", "Mining equipments", "Mining methods", "Blast design and Assessment for surface mines and quarries, underground mines, exploring drilling", "Mining safety", "Mineral processing", "Mining laws", "Mine administration and management"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 372', 'Principles of Geophysics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'second', 3, 'Physics of the earth. Earth structure and composition as revealed by seismology, gravity and magnetic methods. Analysis of electrical properties of rocks. DC resistivity prospecting and data analysis, including instrumentation. Thermal history of the earth and geothermal methods.

Prerequisite: PHY 104, PHY 106', '["Physics of the earth", "Earth structure and composition as revealed by seismology, gravity and magnetic methods", "Analysis of electrical properties of rocks", "DC resistivity prospecting and data analysis, including instrumentation", "Thermal history of the earth and geothermal methods"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 382', 'Engineering Geology I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '300 Level', 'second', 2, 'Formation and Engineering use of Soils; Classification of soils; Engineering properties of soils; Engineering properties of soils and rocks; rock as construction material; Phase relations; Soil improvements; Effective stress.', '["Formation and Engineering use of Soils", "Classification of soils", "Engineering properties of soils", "Engineering properties of soils and rocks", "Rock as construction material", "Phase relations", "Soil improvements", "Effective stress"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 411', 'Petrology of Metamorphic Rocks', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'first', 2, 'Texture, mineralogy, chemistry, mode of occurrence and classification of metamorphic rocks; types; facies and zones of metamorphism; anatexia and migmatites; mineral paragenesis. Systematic petrographic study of major metamorphic rock types. Instrumental analysis of mineral.

Prerequisite: GLG 311', '["Texture, mineralogy, chemistry, mode of occurrence and classification of metamorphic rocks", "Types", "Facies and zones of metamorphism", "Anatexia and migmatites", "Mineral paragenesis", "Systematic petrographic study of major metamorphic rock types", "Instrumental analysis of mineral"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 431', 'Sequence Stratigraphy', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'first', 2, 'Basic concepts: (definition, history of sequence stratigraphy, relative sea level, tectonics, system tracts (LST, TST, HST), controls of systems tracts, tools of sequence stratigraphy - seismic stratigraphy, outcrop and well data, chronostratigraphic charts, and biostratigraphy. Applications to depositional systems and exploration significance; depositional models, system tracts, seismic facies analysis, and classification, reflection character analysis.

Prerequisite: GLG 331, GLG 332', '["Basic concepts: (definition, history of sequence stratigraphy, relative sea level, tectonics, system tracts (LST, TST, HST), controls of systems tracts, tools of sequence stratigraphy - seismic stratigraphy, outcrop and well data, chronostratigraphic charts, and biostratigraphy", "Applications to depositional systems and exploration significance", "Depositional models, system tracts, seismic facies analysis, and classification, reflection character analysis"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 433', 'Regional Geology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'first', 2, 'Distribution and description of Igneous, Metamorphic and sedimentary rocks of Africa; structural development and major tectonic elements of Africa; economic geology of Africa. Survey of world geology.

Prerequisite: GLG 334', '["Distribution and description of Igneous, Metamorphic and sedimentary rocks of Africa", "Structural development and major tectonic elements of Africa", "Economic geology of Africa", "Survey of world geology"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 443', 'Introduction to Palynology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'first', 2, 'Introduction to palynology; sample processing techniques and methods of study: (transmitted light, interference contrast, fluorescence and electron microscopy; Miospores, classification, botanical affinities and biostratigraphy; Cretaceous floral provinces and palaeobiogeography; Acritarchs and other related phytoplankton; Chitinozoa; taxonomic problems and uses in biostratigraphy. Dinoflagellates; life cycle and cyst production; applications in Mesozoic and Tertiary biostratigraphy. Palynomorph colour and fluorescence as indicators of organic maturation level and palaeotemperature, uses of palynomorph data for assessment of hydrocarbon source rock potential.

Prerequisite: GLG 342', '["Introduction to palynology", "Sample processing techniques and methods of study: (transmitted light, interference contrast, fluorescence and electron microscopy", "Miospores, classification, botanical affinities and biostratigraphy", "Cretaceous floral provinces and palaeobiogeography", "Acritarchs and other related phytoplankton", "Chitinozoa", "Taxonomic problems and uses in biostratigraphy", "Dinoflagellates", "Life cycle and cyst production", "Applications in Mesozoic and Tertiary biostratigraphy", "Palynomorph colour and fluorescence as indicators of organic maturation level and palaeotemperature, uses of palynomorph data for assessment of hydrocarbon source rock potential"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 453', 'Petrophysics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'first', 2, 'Introduction to rock physics. Geophysical Well Logging: Definition and basic principles, logging equipment, the sonde, logs and uses: Gamma ray logs and spontaneous potential logs, Resistivity logs, porosity tools such as Density tool, sonic tool, and Neutron tool, pressure prediction from well logs.

Prerequisite: GLG 331, GLG 371', '["Introduction to rock physics", "Geophysical Well Logging: Definition and basic principles, logging equipment, the sonde, logs and uses: Gamma ray logs and spontaneous potential logs, Resistivity logs, porosity tools such as Density tool, sonic tool, and Neutron tool, pressure prediction from well logs"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 461', 'Economic Geology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'first', 3, 'Concept of ore genesis; factors controlling deposition of metallic ores; metallogenic provinces and epochs. Physical and chemical properties, mode of formation, and industrial uses of clays, limestone, evaporates, and coal. Mineral deposits of Nigeria and other parts of the world; techniques for exploration, extraction and evaluation of reserves.', '["Concept of ore genesis", "Factors controlling deposition of metallic ores", "Metallogenic provinces and epochs", "Physical and chemical properties, mode of formation, and industrial uses of clays, limestone, evaporates, and coal", "Mineral deposits of Nigeria and other parts of the world", "Techniques for exploration, extraction and evaluation of reserves"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 465', 'Environmental Geology and Waste Management', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'first', 2, 'Principles of health, safety and environment (HSE); Fossils fuels, surface and underground water hydrology; pollution and its sources, hazards and control; waste management strategies; prediction and control of geologic hazards; environmental impact assessment (EIA) studies; GIS in environmental studies.

Prerequisite: GLG 331, GLG 332', '["Principles of health, safety and environment (HSE)", "Fossils fuels, surface and underground water hydrology", "Pollution and its sources, hazards and control", "Waste management strategies", "Prediction and control of geologic hazards", "Environmental impact assessment (EIA) studies", "GIS in environmental studies"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 492', 'Students Industrial Work Experience (SIWES)', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'second', 8, 'The student on SIWES is mandated to complete the Log Book daily as a record of actual industrial activity carried out. The industrial-based supervisor goes through the log book to authenticate the students'' report. The institutional supervisors (Lecturers from the department) equally visit at least twice to authenticate the students'' log book report and review the training programme in conjunction with the industry-based supervisor. Log Book, punctuality, general conduct and log book report account for the student''s score.', '["The student on SIWES is mandated to complete the Log Book daily as a record of actual industrial activity carried out", "The industrial-based supervisor goes through the log book to authenticate the students'' report", "The institutional supervisors (Lecturers from the department) equally visit at least twice to authenticate the students'' log book report and review the training programme in conjunction with the industry-based supervisor", "Log Book, punctuality, general conduct and log book report account for the student''s score"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 494', 'SIWES Technical Report', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'second', 4, 'The student shall produce a scientific write-up on the experimental procedure, techniques, use of the equipment, result interpretation and general presentation. The technical report should be usually submitted to the Department at the end of the SIWES.', '["The student shall produce a scientific write-up on the experimental procedure, techniques, use of the equipment, result interpretation and general presentation", "The technical report should be usually submitted to the Department at the end of the SIWES"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 496', 'SIWES Seminar', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '400 Level', 'second', 3, 'After due consultation with the institutional supervisor, the student presents to the departmental audience (staff and students) a seminar to showcase the knowledge acquired during the industrial training. The students shall be rated by the staff who award grade to the student based on performance in the seminar.', '["After due consultation with the institutional supervisor, the student presents to the departmental audience (staff and students) a seminar to showcase the knowledge acquired during the industrial training", "The students shall be rated by the staff who award grade to the student based on performance in the seminar"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 511', 'Advanced Petrology of Igneous and Metamorphic Rocks', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '500 Level', 'first', 2, 'Study of igneous and metamorphic rocks emphasizing distribution, genetic relationship, petrography and petrogenesis; treatment of selected metamorphic minerals and their stability field; discussion of some typical igneous and metamorphic areas of the world with emphases on Nigeria.

Prerequisite: GLG 311, GLG 411', '["Study of igneous and metamorphic rocks emphasizing distribution, genetic relationship, petrography and petrogenesis", "Treatment of selected metamorphic minerals and their stability field", "Discussion of some typical igneous and metamorphic areas of the world with emphases on Nigeria"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 512', 'Geochemistry', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '500 Level', 'second', 2, 'Geochemical classification of elements, meteorites, distribution of elements in the cosmic system lithospheric hydrosphere, and atmosphere; geochemical cycles of some selected elements; geochemistry of different rock types; weathering and soil formation; principles and methods of exploration geochemistry and geochemical analysis; chemistry of petroleum and coal.', '["Geochemical classification of elements, meteorites, distribution of elements in the cosmic system lithospheric hydrosphere, and atmosphere", "Geochemical cycles of some selected elements", "Geochemistry of different rock types", "Weathering and soil formation", "Principles and methods of exploration geochemistry and geochemical analysis", "Chemistry of petroleum and coal"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 541', 'Biostratigraphy', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '500 Level', 'first', 3, 'Basic concepts in Biostratigraphy. Biostratigraphic study emphasis on Ammonites, Pelecypoda, gastropoda, foraminifera, ostracode and pollen and spores from Nigeria. Statistical data analysis of paleontological data.

Prerequisite: GLG 341', '["Basic concepts in Biostratigraphy", "Biostratigraphic study emphasis on Ammonites, Pelecypoda, gastropoda, foraminifera, ostracode and pollen and spores from Nigeria", "Statistical data analysis of paleontological data"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 553', 'Petrophysics II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '500 Level', 'first', 2, 'Rock properties: moduli, estimation of petrophysical properties such as porosity, permeability, fluid saturation, productivity, porosity/lithologic, thin bed thickness etc; cross plotting techniques; general formation evaluation, volume visualization and estimation. Rock analysis: relationship between interval velocity and porosity, porosity and permeability, Vp/Vs and saturation and lithology. Introduction to some available petrophysical softwares.

Prerequisite: GLG 453', '["Rock properties: moduli, estimation of petrophysical properties such as porosity, permeability, fluid saturation, productivity, porosity/lithologic, thin bed thickness etc", "Cross plotting techniques", "General formation evaluation, volume visualization and estimation", "Rock analysis: relationship between interval velocity and porosity, porosity and permeability, Vp/Vs and saturation and lithology", "Introduction to some available petrophysical softwares"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 562', 'Marine Geology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '500 Level', 'second', 2, 'History of oceanographic expeditions and research; elements of physical oceanography; oceans and climates; chemical, physical and biological aspects of oceans; description and origin of main physiographic features of oceans; resources of oceans, their exploration and exploitation; ocean laws, management and conservation.', '["History of oceanographic expeditions and research", "Elements of physical oceanography", "Oceans and climates", "Chemical, physical and biological aspects of oceans", "Description and origin of main physiographic features of oceans", "Resources of oceans, their exploration and exploitation", "Ocean laws, management and conservation"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 571', 'Applied Geophysics', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '500 Level', 'first', 3, 'Seismic prospecting methods; Induced Polarization; Electromagnetic methods, Geophysical method in hydrogeology and engineering geology.

Prerequisite: GLG 371', '["Seismic prospecting methods", "Induced Polarization", "Electromagnetic methods, Geophysical method in hydrogeology and engineering geology"]'::jsonb, 'Department of Geology handbook'),
  ('GLG 572', 'Petroleum Geology', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '500 Level', 'second', 3, 'Composition, origin, maturation of petroleum, migration and accumulation of petroleum; source, reservoir and cap rocks; types of traps; drilling, logging and production; reservoir and reserve estimation; recovery and exploration; geographical distribution of petroleum.', '["Composition, origin, maturation of petroleum, migration and accumulation of petroleum", "Source, reservoir and cap rocks", "Types of traps", "Drilling, logging and production", "Reservoir and reserve estimation", "Recovery and exploration", "Geographical distribution of petroleum"]'::jsonb, 'Department of Geology handbook'),
  ('BIO 151', 'General Biology I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 3, 'Elective.', '[]'::jsonb, 'Department of Computer Science course outline'),
  ('CHM 101', 'Basic Principles of Inorganic Chemistry', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 2, 'Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories. Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position. Nuclear Chemistry: Radioactivity and its practical applications.', '["Stoichiometry and Atomic Structure: Stoichiometry and mole concept. Introduction to atomic structure, development of electronic configuration of the elements, and valency theories", "Periodic Table and Groups: The periodic classification of elements. Brief group study of representative elements, with emphasis on similarities and differences based on periodic position", "Nuclear Chemistry: Radioactivity and its practical applications"]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
  ('MTH 111', 'Elementary Mathematics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 3, 'Elementary Set theory, subsets, union, intersection, complements. Venn diagrams, Real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem. Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae. Complex numbers, algebra of complex numbers, the Argand Diagram, De Moivre''s theorem, $n$th roots of unity.', '["Elementary Set theory, subsets, union, intersection, complements", "Venn diagrams, Real numbers, integers, rational and irrational numbers, mathematical induction, real sequences and series, theory of quadratic equations, binomial theorem", "Circular measure, trigonometric functions of angles of any magnitude, addition and factor formulae", "Complex numbers, algebra of complex numbers, the Argand Diagram, De Moivre''s theorem, $n$th roots of unity"]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
  ('MTH 121', 'Elementary Mathematics II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 3, 'Functions of a real variable, graphs, limits and continuity. The derivative as limit of rate of change. Techniques of differentiation. Curve sketching, integration as an inverse of differentiation. Methods of integration, definite integrals. Application of integration to areas and volumes.', '["Functions of a real variable, graphs, limits and continuity", "The derivative as limit of rate of change", "Techniques of differentiation", "Curve sketching, integration as an inverse of differentiation", "Methods of integration, definite integrals", "Application of integration to areas and volumes"]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
  ('PHY 123', 'General Physics for Physical Sciences I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 2, 'Elective.', '[]'::jsonb, 'Department of Statistics undergraduate course module'),
  ('PHY 191', 'Practical Physics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 2, 'Selected experiments from the 100-Level courses in Physics for service courses.', '["Selected experiments from the 100-Level courses in Physics for service courses"]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
  ('GSP 101', 'The Use of English I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 2, 'Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, The English Language and the Nigerian society, World English, Levels and Varieties of English — formal, informal, standard, etc., English in Literature and the Media.

Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes, English Language Register, diatypes and dialects.

Listening skill - The listening skill discussed as a receptive and reciprocal activity, Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening.

Reading Skill - The concept of reading as a linguistic organization and a vehicle of communication. Reading Problems, Levels of Reading, Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies (Scanning, Skimming, Phrase reading, Intensive & Extensive reading, Exploiting the topic sentence for main ideas), Reading for details, Reading for evaluation and inference, Reading with questions - SQ3R, PR3, Methods for understanding difficult words in a reading text, Literature reading for study, analysis and comment.

Speaking & Communication Skills - Nature, Process & Development, Principles of Public Speech Making and Social Interaction, The Speech Sounds of English and their Articulation, Phonetic Transcription and Practical Speech Work.

Study Techniques - Choosing study centers and discussion groups, Note-taking during lectures, and from audio-visual equipment, Note-making techniques during private reading and literature search, Summary & Transcoding Techniques, Retrieving information from notes, The dictionary as a study guide.

Basic Research Methods & Term Paper Writing - Research – meaning & nature, Types & Methodology; Data in the Research Process, The Research Report, Process and Techniques, Documentation in Research Reports: Process, Types and Methods, Abbreviations in Research Reports, The term paper as a miniature research report, Practical term paper writing.

Course Evaluation & Grading - Students must attend at least 75% of the lectures to qualify for examination in the course.', '["Man, Society and Language - The Nature, Characteristics and Functions of Language, Human Communication & Language, World English, Levels and Varieties of English", "Vocabulary of English - Types, Method of Vocabulary Development, Synonyms, Antonyms, Homonyms, Acronyms, Paronyms, Affixation and other morphological processes", "Listening skill - Nature, Types, Purposes and Factors that affect Listening, Strategies and Aids for Effective Listening", "Reading Skill - Reading Problems, Levels and Types of Reading, Causes and Remedies of Reading Failures, Reading Techniques & Strategies, Reading for evaluation and inference", "Speaking & Communication Skills - Principles of Public Speech Making and Social Interaction, Phonetic Transcription and Practical Speech Work", "Study Techniques - Note-taking, Note-making, Summary & Transcoding Techniques", "Basic Research Methods & Term Paper Writing - The Research Report, Documentation, Abbreviations, practical term paper writing"]'::jsonb, 'Department of Mechanical Engineering handbook'),
  ('PHY 125', 'Fundamentals of Physics I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 3, 'Elective.', '[]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
  ('FRE 101', 'Elementary French I', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '100 Level', 'first', 2, 'Elective.', '[]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
