  ('GSP 207', 'Humanities', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '200 Level', 'first', 2, '', '[]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
  ('STA 206', 'Statistics for Physical Sciences and Engineering II', 'University of Nigeria, Nsukka', 'Faculty of Physical Sciences', 'Geology', '200 Level', 'second', 2, 'Estimation: point and interval. Test of significance. Regression and correlation. Analysis of variance: one-way and two-way with no interaction.', '["Estimation: point and interval", "Test of significance", "Regression and correlation", "Analysis of variance: one-way and two-way with no interaction"]'::jsonb, 'Faculty of Physical Sciences course catalogue (2014/2015)'),
